<?php

namespace Database\Factories;

use App\Models\Order;
use App\Models\Package;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * @extends Factory<Order>
 */
class OrderFactory extends Factory
{
    protected $model = Order::class;

    /**
     * reference and tracking_code_hash are deliberately absent: both are
     * generated by the model on create, and a factory that supplied them
     * would be testing the factory rather than the thing that has to be
     * unguessable in production.
     */
    public function definition(): array
    {
        return [
            'package_id' => Package::factory(),
            'lead_id' => null,
            'user_id' => null,
            'client_name' => $this->faker->name(),
            'client_email' => $this->faker->unique()->safeEmail(),
            'client_phone' => '+9665'.$this->faker->numerify('########'),
            'total' => $this->faker->randomFloat(2, 2000, 80000),
            'currency' => 'SAR',
            'placed_at' => now()->subDays($this->faker->numberBetween(1, 90)),
        ];
    }

    // status and progress are guarded — assigned, never filled.

    public function inProgress(int $progress = 45): static
    {
        return $this->withState(Order::STATUS_IN_PROGRESS, $progress);
    }

    public function completed(): static
    {
        return $this->withState(Order::STATUS_COMPLETED, 100);
    }

    public function cancelled(): static
    {
        return $this->withState(Order::STATUS_CANCELLED, 0);
    }

    private function withState(string $status, int $progress): static
    {
        return $this->afterMaking(function (Order $order) use ($status, $progress) {
            $order->status = $status;
            $order->setProgress($progress);
        })->afterCreating(function (Order $order) use ($status, $progress) {
            $order->status = $status;
            $order->setProgress($progress);

            if ($status === Order::STATUS_COMPLETED) {
                $order->completed_at ??= now();
            }

            $order->save();
        });
    }
}
